# Testing for small n
def test_small_n(n):
    v_even = 0
    v_odd = 0
    for v in range(-(n-1), n):
        low = abs(v)
        high = n - 1 - abs(v)
        if low <= high:
            count = high - low + 1
            if count % 2 == 0:
                v_even += count // 2
                v_odd += count // 2
            else:
                if (low + v) % 2 == 0:
                    v_even += (count + 1) // 2
                    v_odd += count // 2
                else:
                    v_even += count // 2
                    v_odd += (count + 1) // 2
    B = v_even + v_odd
    n2 = min(v_even, v_odd)
    N = B - n2
    return v_even, v_odd, B, n2, N

for n in [1, 3, 5]:
    print(f"n={n}:", test_small_n(n))

def solve_correct_v5():
    n = 2025
    total_count = 0
    for v in range(-(n-1), n):
        low = abs(v)
        high = n - 1 - abs(v)
        if low <= high:
            total_count += (high - low + 1)
    print(f"total_count: {total_count}")

solve_correct_v5()
